// Cutscene: skills are installed beside skills/cutscene/, whose engine.json pins the engine.
function readCutscenePin() {
  try {
    const pin = JSON.parse(readFileSync(join(HERE, "..", "..", "cutscene", "engine.json"), "utf8")).hyperframes;
    return typeof pin === "string" && pin ? pin : null;
  } catch {
    return null;
  }
}

function readBundledHyperframesVersion() {

throw new Error(
  `Cutscene could not find the pinned engine version for ${packageName}. Set ${VERSION_OVERRIDE_ENV}=<version> or check skills/cutscene/engine.json.`,
);

  // Cutscene: the media library lives under Cutscene home (contracts: <CUTSCENE_HOME>/media).
  return join(process.env.CUTSCENE_HOME || join(homedir(), ".cutscene"), "media");
}

// Cutscene: WhisperX is opt-in. `uvx` would otherwise download WhisperX, PyTorch and models
// (unpinned dependencies, no checksums) without asking; the engine's Whisper asks first.
const wantWx = process.env.TRANSCRIBE_ENGINE === "whisperx";
